            <FormField
                label="Full Name"
                type="text"
                id="fullName"
                required={true}
                value={formData.fullName}
                onChange={handleChange}
            />
            <FormField
                label="Email Address"
                type="email"
                id="email"
                required={true}
                value={formData.email}
                onChange={handleChange}
            />
            <FormField
                label="Phone Number"
                type="tel"
                id="phone"
                required={false}
                helperText="Expected format: (555) 555-5555"
                value={formData.phone}
                onChange={handleChange}
            />
            <button type="submit">Submit</button>
        </form>
    );
};

const App = () => {
    return (
        <div className="container">
            <h1>Contact Support</h1>
            <ContactForm />
        </div>
    );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
